import {expect,test,type Page} from '@playwright/test';
import {mkdir,readFile,writeFile} from 'node:fs/promises';
import {randomUUID} from 'node:crypto';
import {allRoutes} from '../../apps/web/src/core/navigation';
const password=process.env.AV8_BOOTSTRAP_PASSWORD;
if(!password)throw new Error('Private AV8_BOOTSTRAP_PASSWORD required for isolated QA');
const out='output/playwright/final-delivery';
const testTokens=new WeakMap<Page,string>();
const observedPages=new WeakSet<Page>();
function observeSession(page:Page){if(observedPages.has(page))return;observedPages.add(page);page.on('request',request=>{if(!new URL(request.url()).pathname.startsWith('/api/'))return;const header=request.headers().authorization;if(header?.startsWith('Bearer '))testTokens.set(page,header.slice(7));});page.on('response',async response=>{if(!/^\/api\/auth\/(login|refresh|mfa\/verify)$/.test(new URL(response.url()).pathname)||!response.ok())return;const payload=await response.json().catch(()=>null);const token=payload?.accessToken||payload?.token;if(token)testTokens.set(page,token);});}
async function login(page:Page,email='admin@av8.local'){
 observeSession(page);
 await page.goto('/login');await page.getByTestId('login-email').fill(email);await page.getByTestId('login-password').fill(password!);await page.getByTestId('login-submit').click();await expect(page.locator('.classic-shell')).toBeVisible();await expect(page).not.toHaveURL(/\/login$/);await expect(page.locator('.loading')).toHaveCount(0);
 if(await page.locator('html').getAttribute('lang')==='ar')await page.getByTestId('language-toggle').click();await expect(page.locator('html')).toHaveAttribute('dir','ltr');
}
async function auth(page:Page){const token=testTokens.get(page);if(!token)throw new Error('No actual session token captured by the isolated test');return {Authorization:`Bearer ${token}`};}
async function post(page:Page,path:string,data:any){const response=await page.request.post('/api'+path,{headers:{...await auth(page),'Idempotency-Key':randomUUID()},data});expect(response.ok(),await response.text()).toBe(true);return response.json();}
async function ready(page:Page){await expect(page.locator('main h1')).toBeVisible();await expect(page.locator('.loading')).toHaveCount(0);await expect(page.locator('.error-notice')).toHaveCount(0);await expect(page.locator('main h1')).not.toHaveText(/Access Denied|404|غير مصرح/);}

test('registered routes render against real API in both languages, themes and viewport sizes',async({page})=>{
 await mkdir(out,{recursive:true});await login(page);const rows:any[]=[];const failures:string[]=[];let errors:string[]=[];page.on('pageerror',e=>errors.push(e.message));
 const variants=[{language:'en',theme:'light',width:1440,height:1000},{language:'ar',theme:'dark',width:1440,height:1000},{language:'en',theme:'dark',width:390,height:844},{language:'ar',theme:'light',width:390,height:844}];
 for(const variant of variants){await page.setViewportSize({width:variant.width,height:variant.height});await page.evaluate(({language,theme})=>{localStorage.setItem('av8_language',language);localStorage.setItem('odin-theme',theme);document.cookie=`av8_language=${language}; path=/; samesite=lax`;},variant);
  for(const {module,child} of allRoutes){errors=[];const failedRequests:string[]=[];const responseListener=(response:any)=>{if(response.url().includes('/api/')&&response.status()>=400)failedRequests.push(`${response.status()} ${new URL(response.url()).pathname}`);};page.on('response',responseListener);let status='PASS',issue='';
   try{await page.goto(child.route);await ready(page);await expect(page.locator('html')).toHaveAttribute('dir',variant.language==='ar'?'rtl':'ltr');await expect(page.locator('html')).toHaveAttribute('data-theme',variant.theme);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'page horizontal overflow').toBe(true);expect(errors,'browser errors').toEqual([]);expect(failedRequests,'API errors').toEqual([]);
    if(child.route===module.children[0]?.route)await page.screenshot({path:`${out}/${module.id}-${variant.language}-${variant.theme}-${variant.width}.png`,fullPage:true});
   }catch(error){status='FAIL';issue=String(error).split('\n').slice(0,8).join('\n');failures.push(`${child.route} ${variant.language}/${variant.theme}/${variant.width}: ${issue}`);await page.screenshot({path:`${out}/failure-${rows.length}.png`,fullPage:true}).catch(()=>{});}
   page.off('response',responseListener);rows.push({route:child.route,...variant,status,issue,browserErrors:errors,failedRequests});await writeFile(`${out}/route-results.json`,JSON.stringify(rows,null,2));
  }
 }
 expect(failures).toEqual([]);
});

