test('role restrictions remain visible and direct protected APIs reject unauthorized roles',async({browser})=>{
 const results:any[]=[];for(const [role,path,forbidden] of [['telesales','/av8/leads','/api/av8/policies'],['sales','/av8/students','/api/av8/funds'],['affairs','/av8/affairs','/api/av8/funds'],['finance','/av8/finance','/api/av8/leads'],['management','/av8/reports',null]]){const context=await browser.newContext({baseURL:process.env.PLAYWRIGHT_BASE_URL||'http://127.0.0.1:8180'});const page=await context.newPage();await login(page,`${role}@av8.local`);await page.goto(path!);await ready(page);if(forbidden){const response=await page.request.get(forbidden,{headers:await auth(page)});expect(response.status(),`${role} ${forbidden}`).toBe(403);}results.push({role,route:path,status:'PASS',forbiddenApi:forbidden});await context.close();}await writeFile(`${out}/role-results.json`,JSON.stringify(results,null,2));
});

