test('opening supplier settlement links actual posted payment without duplicating cash or journals',async({page})=>{
 const fixture=JSON.parse(await readFile(process.env.AV8_SUPPLIER_UAT_FIXTURE||'.av8/supplier-uat-fixture.json','utf8'));expect(fixture.synthetic).toBe(true);await login(page);
 const get=async(path:string)=>{const response=await page.request.get('/api'+path,{headers:await auth(page)});expect(response.ok(),await response.text()).toBe(true);return response.json();};
 const balances=(batches:any[])=>batches.flatMap(batch=>batch.supplierBalances||[]);const match=(row:any)=>row.sourceSystem===fixture.sourceSystem&&row.batchSourceId===fixture.batchSourceId&&row.balanceIndex===fixture.balanceIndex;
 const beforeHistory=await get('/av8/opening');const before=balances(beforeHistory).find(match);expect(before,'Prepare fresh synthetic supplier fixture before each full acceptance run').toBeTruthy();expect(before.remainingMinor).toBe('100000');const beforeBank=await get(`/banking?bankAccountId=${fixture.bankAccountId}`),beforeJournals=await get('/journals');const movement=beforeBank.transactions.find((row:any)=>row.id===fixture.bankTransactionId);expect(movement).toBeTruthy();
 await page.goto('/av8/settings');await ready(page);await page.getByRole('row').filter({hasText:fixture.supplierName}).getByRole('button',{name:'Link posted supplier settlement',exact:true}).click();const dialog=page.getByRole('dialog');await dialog.getByLabel('Or enter the posted bank transaction ID').fill(fixture.bankTransactionId);await dialog.getByLabel('Payment evidence reference').fill(fixture.evidenceReference);await dialog.getByLabel('Reason / notes').fill(fixture.reason);const saved=page.waitForResponse(response=>response.url().endsWith('/api/av8/opening/supplier-settlement'));await dialog.getByRole('button',{name:'Save',exact:true}).click();const response=await saved;expect(response.ok(),await response.text()).toBe(true);await expect(dialog).toHaveCount(0);await ready(page);
 const after=balances(await get('/av8/opening')).find(match);expect(after.paidMinor).toBe('40000');expect(after.remainingMinor).toBe('60000');expect(after.settlements).toHaveLength(1);expect(after.settlements[0].bankTransactionId).toBe(fixture.bankTransactionId);const afterBank=await get(`/banking?bankAccountId=${fixture.bankAccountId}`),afterJournals=await get('/journals');expect(afterBank.transactions).toHaveLength(beforeBank.transactions.length);expect(afterBank.transactions.find((row:any)=>row.id===fixture.bankTransactionId)).toEqual(movement);expect(Array.isArray(afterJournals)?afterJournals.length:afterJournals.rows.length).toBe(Array.isArray(beforeJournals)?beforeJournals.length:beforeJournals.rows.length);await expect(page.getByRole('row').filter({hasText:fixture.supplierName}).filter({hasText:'EGP 600.00'})).toBeVisible();await page.screenshot({path:`${out}/opening-supplier-settlement-en.png`,fullPage:true});await writeFile(`${out}/supplier-settlement.json`,JSON.stringify({synthetic:true,sourceSystem:fixture.sourceSystem,remainingMinor:after.remainingMinor,currency:after.currency,cashCountUnchanged:true,journalCountUnchanged:true},null,2));
});


