 await studentTab(page,c.id,'Report delivery');await page.getByRole('row').filter({has:page.getByRole('cell',{name:'2',exact:true})}).getByRole('button',{name:'Queue report emails',exact:true}).click();await reasonModal(page,`/av8/applications/${c.id}/reports/${revision.id}/dispatch`);expect((await operationsState(page,c.id)).dispatches).toHaveLength(4);const first=(await operationsState(page,c.id)).dispatches[0];await page.getByRole('button',{name:'Retry failed recipient',exact:true}).first().click();await page.getByRole('dialog').getByLabel('Reason / notes').fill('Synthetic blocked-provider retry must remain visible');const retry=page.waitForResponse(response=>response.url().endsWith(`/api/av8/applications/${c.id}/dispatches/${first.id}/action`)&&response.request().method()==='POST');await page.getByRole('dialog').getByRole('button',{name:'Save',exact:true}).click();expect((await retry).status()).toBe(400);await expect(page.getByRole('dialog').locator('.error-notice')).toContainText(/disabled|configure/i);page.once('dialog',dialog=>dialog.accept());await page.getByRole('dialog').getByRole('button',{name:'Cancel',exact:true}).click();await expect(page.getByRole('dialog')).toHaveCount(0);state=await operationsState(page,c.id);expect(state.dispatches).toHaveLength(4);expect(state.dispatches.every((dispatch:any)=>dispatch.status===c.expectedDelivery)).toBe(true);await page.screenshot({path:`${out}/affairs-versioned-delivery-blocked.png`,fullPage:true});
