test('treasury paired transfer UI posts one balanced journal and two actual resource movements despite a lost response',async({page})=>{
 await login(page);const refs=await(await page.request.get('/api/bootstrap',{headers:await auth(page)})).json();const resources=refs.bankAccounts.filter((bank:any)=>bank.currency==='EGP');expect(resources.length).toBeGreaterThanOrEqual(2);const source=resources[0],destination=resources[1],expense=refs.accounts.find((account:any)=>account.code==='SYN-UAT-FEE-EXP');expect(expense).toBeTruthy();const banking=async()=>{const response=await page.request.get('/api/banking',{headers:await auth(page)});expect(response.ok()).toBe(true);return response.json();};const before=await banking();await page.goto('/banking/transactions');await ready(page);await page.getByRole('button',{name:'Transfer between resources',exact:true}).click();await page.getByLabel('Branch',{exact:false}).selectOption(refs.branches.find((branch:any)=>branch.code==='CAI').id);await page.getByLabel('Source resource').selectOption(source.id);await page.getByLabel('Destination resource').selectOption(destination.id);await page.getByLabel('Source principal amount').fill('10.00');await page.getByLabel('Destination principal amount').fill('10.00');await page.getByLabel('Fee in source currency').fill('1.00');await page.getByLabel('Fee expense account').selectOption(expense.id);await page.getByLabel('Rate provenance or evidence reference').fill('SYNTHETIC actual same-currency bank transfer slip; no exchange conversion');const reference=`SYNTHETIC-UI-TRANSFER-${Date.now()}`;await page.getByLabel('Reference',{exact:true}).fill(reference);await page.getByLabel('Transfer reason').fill('Synthetic local paired-resource acceptance');let committed:any,firstKey='';await page.route('**/api/banking/transfers',async route=>{firstKey=route.request().headers()['idempotency-key'];const response=await route.fetch();expect(response.ok(),await response.text()).toBe(true);committed=await response.json();await route.abort('failed');},{times:1});await page.getByRole('button',{name:'Post paired transfer',exact:true}).click();await expect(page.locator('.error-notice')).toBeVisible();const afterCommit=await banking();const replay=page.waitForResponse(response=>response.url().endsWith('/api/banking/transfers')&&response.request().method()==='POST');await page.getByRole('button',{name:'Post paired transfer',exact:true}).click();const response=await replay;expect(response.ok(),await response.text()).toBe(true);expect(response.request().headers()['idempotency-key']).toBe(firstKey);expect(await response.json()).toEqual(committed);await ready(page);const after=await banking();expect(after.transactions.map((row:any)=>row.id)).toEqual(afterCommit.transactions.map((row:any)=>row.id));expect(after.transactions.filter((row:any)=>!before.transactions.some((old:any)=>old.id===row.id))).toHaveLength(2);const outgoing=after.transactions.find((row:any)=>row.id===String(committed.outgoing.id)),incoming=after.transactions.find((row:any)=>row.id===String(committed.incoming.id));expect(outgoing).toMatchObject({kind:'TRANSFER_OUT',amountMinor:'1100',bankAccountId:source.id});expect(incoming).toMatchObject({kind:'TRANSFER_IN',amountMinor:'1000',bankAccountId:destination.id});expect(outgoing.journalEntryId).toBe(incoming.journalEntryId);const journal=await(await page.request.get(`/api/journals/${committed.journalId}`,{headers:await auth(page)})).json();expect(journal.status).toBe('POSTED');expect(journal.lines.reduce((sum:bigint,row:any)=>sum+BigInt(row.debitMinor)-BigInt(row.creditMinor),0n)).toBe(0n);expect(journal.lines.some((row:any)=>row.accountId===expense.id&&row.debitMinor==='100')).toBe(true);await page.getByRole('searchbox',{name:'Search posted transactions',exact:true}).fill(reference);await expect(page.locator('tbody tr')).toHaveCount(2);await page.getByLabel('Cash / bank account').selectOption(source.id);await expect(page.locator('tbody tr')).toHaveCount(1);await expect(page.locator('tbody tr')).toContainText(outgoing.number);await page.getByRole('searchbox',{name:'Search posted transactions',exact:true}).fill('');await page.getByLabel('Cash / bank account').selectOption('');const firstPage=page.waitForResponse(response=>{const url=new URL(response.url());return url.pathname==='/api/banking'&&url.searchParams.get('transactionPageSize')==='25'&&url.searchParams.get('transactionPage')==='1';});await page.getByLabel('Transaction rows per page').selectOption('25');const firstRows=await(await firstPage).json();expect(firstRows.transactionPagination.total).toBeGreaterThan(25);const nextPage=page.waitForResponse(response=>new URL(response.url()).searchParams.get('transactionPage')==='2');await page.getByRole('button',{name:'Next page',exact:true}).click();const nextRows=await(await nextPage).json();expect(nextRows.transactions.every((row:any)=>!firstRows.transactions.some((first:any)=>first.id===row.id))).toBe(true);await page.getByRole('button',{name:'Previous page',exact:true}).click();await ready(page);await page.screenshot({path:`${out}/treasury-paired-transfer.png`,fullPage:true});
 await page.goto('/banking/statements');await ready(page);await page.getByRole('button',{name:'Preview bank statement import',exact:true}).click();await page.getByLabel('Bank account').selectOption(source.id);await page.getByLabel('Opening balance').fill('0');await page.getByLabel('Closing balance').fill('-11');await page.getByLabel('Statement CSV').fill(`date,amount,description,reference\n2026-10-31,-11.00,Synthetic actual paired transfer evidence,${reference}`);await page.getByRole('button',{name:'Preview import',exact:true}).click();await expect(page.getByRole('heading',{name:'Statement preview',exact:true})).toBeVisible();const imported=page.waitForResponse(response=>response.url().endsWith('/api/banking/statements')&&response.request().method()==='POST');await page.getByRole('button',{name:'Import validated statement',exact:true}).click();const statement=await(await imported).json();await ready(page);await page.getByRole('searchbox',{name:'Search bank statements',exact:true}).fill(reference);await expect(page.locator('tbody tr')).toHaveCount(1);await page.getByRole('row').filter({hasText:reference}).getByRole('button',{name:'Match posted transaction by ID',exact:true}).click();await page.getByLabel('Posted bank transaction ID').fill(String(committed.outgoing.id));const matched=page.waitForResponse(response=>response.url().endsWith(`/api/banking/statement-lines/${statement.lines[0].id}/match`)&&response.request().method()==='POST');await page.getByRole('button',{name:'Confirm match',exact:true}).click();expect((await matched).ok()).toBe(true);await ready(page);await expect(page.getByRole('row').filter({hasText:reference})).toContainText('Matched');const final=await banking();expect(final.transactions.map((row:any)=>row.id)).toEqual(after.transactions.map((row:any)=>row.id));expect(final.transactions.find((row:any)=>row.id===String(committed.outgoing.id)).reconciled).toBe(true);await page.screenshot({path:`${out}/treasury-reconciled-transfer.png`,fullPage:true});await page.getByRole('searchbox',{name:'Search bank statements',exact:true}).fill('');const firstStatementPage=page.waitForResponse(response=>{const url=new URL(response.url());return url.pathname==='/api/banking'&&url.searchParams.get('statementPageSize')==='1'&&url.searchParams.get('statementPage')==='1';});await page.getByLabel('Statements per page').selectOption('1');const firstStatementRows=await(await firstStatementPage).json();expect(firstStatementRows.statementPagination.total).toBeGreaterThan(1);const nextStatementPage=page.waitForResponse(response=>new URL(response.url()).searchParams.get('statementPage')==='2');await page.getByRole('button',{name:'Next page',exact:true}).click();const nextStatementRows=await(await nextStatementPage).json();expect(nextStatementRows.statements[0].id).not.toBe(firstStatementRows.statements[0].id);await page.getByRole('button',{name:'Previous page',exact:true}).click();await ready(page);await writeFile(`${out}/treasury-paired-transfer.json`,JSON.stringify({synthetic:true,journalId:committed.journalId,movementsCreated:2,sourcePrincipalMinor:'1000',feeMinor:'100',sourceDebitedMinor:'1100',destinationCreditedMinor:'1000',sameResponseOnRetry:true,historySearchAndPagination:true,statementSearchAndPagination:true,statementMatchedBySourceId:true},null,2));
});

test('opening import UI rejects malformed and unbalanced files, preserves original evidence, and replays without new cash or journals',async({page})=>{
 const fixture=JSON.parse(await readFile('.av8/opening-uat-fixture.json','utf8'));expect(fixture.synthetic).toBe(true);const manifest=JSON.parse(await readFile(fixture.manifestPath,'utf8'));await login(page,'finance@av8.local');const get=async(path:string)=>{const response=await page.request.get('/api'+path,{headers:await auth(page)});expect(response.ok(),await response.text()).toBe(true);return response.json();};const beforeBank=await get(`/banking?bankAccountId=${fixture.bankAccountId}`),beforeJournal=await get(`/journals/${manifest.openingJournalId}`);const beforeHistory=await get('/av8/opening');expect(beforeHistory.filter((batch:any)=>batch.source_system===manifest.sourceSystem)).toHaveLength(0);await page.goto('/av8/settings');await ready(page);const panel=page.locator('section.surface').filter({has:page.getByRole('heading',{name:'Opening balances and historical students',exact:true})}),file=panel.locator('input[type="file"]');
 await file.setInputFiles({name:'synthetic-malformed.json',mimeType:'application/json',buffer:Buffer.from('{invalid')});await expect(panel.locator('.error-notice')).toContainText('Choose a valid opening JSON file');await expect(panel.getByRole('button',{name:'Preview opening import',exact:true})).toBeDisabled();const preview=async(value:any,name:string)=>{await file.setInputFiles({name,mimeType:'application/json',buffer:Buffer.from(JSON.stringify(value))});const response=page.waitForResponse(response=>response.url().endsWith('/api/av8/opening/preview')&&response.request().method()==='POST');await panel.getByRole('button',{name:'Preview opening import',exact:true}).click();const result=await response;expect(result.ok(),await result.text()).toBe(true);return result.json();};
 const bad=structuredClone(manifest);bad.expectedTotals.studentPaidMinor=String(BigInt(bad.expectedTotals.studentPaidMinor)+1n);const invalid=await preview(bad,'synthetic-unbalanced.json');expect(invalid.valid).toBe(false);expect(invalid.errors.length).toBeGreaterThan(0);await expect(panel.getByRole('button',{name:'Commit reviewed opening import',exact:true})).toBeDisabled();const reviewed=await preview(manifest,'synthetic-reviewed-opening.json');expect(reviewed.valid).toBe(true);expect(reviewed.totals).toEqual(manifest.expectedTotals);expect(reviewed.createsCashTransactions).toBe(false);const commit=async(reason:string)=>{await panel.getByRole('button',{name:'Commit reviewed opening import',exact:true}).click();await page.getByRole('dialog').getByLabel('Reason / notes').fill(reason);return saveModal(page,'/av8/opening/commit');};const imported=await commit('Synthetic reviewed opening cutover; original source and independently approved opening journal verified');expect(imported.createdCashTransactions).toBe(0);expect(imported.createdJournals).toBe(0);expect(imported.applications).toHaveLength(manifest.applications.length);await expect(panel.getByRole('status')).toContainText('Opening import recorded');await page.screenshot({path:`${out}/opening-import-committed.png`,fullPage:true});
 const originals:any[]=[];for(const mapping of imported.applications){const source=manifest.applications.find((row:any)=>row.sourceId===mapping.sourceId),app=await application(page,mapping.applicationId);expect(app.reference).toBe(source.reference);expect(app.finance.schedule).toHaveLength(source.schedule.length);for(const charge of source.schedule){const saved=app.finance.schedule.find((row:any)=>row.id===mapping.charges[charge.sourceId]);expect(saved.amountMinor).toBe(charge.amountMinor);expect(saved.paidMinor).toBe(charge.paidMinor||'0');}if(source.contract){const contract=app.records.find((row:any)=>row.id===mapping.contractId);expect(contract.status).toBe('SIGNED');expect(contract.data.originalReference).toBe(source.contract.reference);if(source.contract.policyReference)expect(contract.data.legalPolicyReference).toBe(source.contract.policyReference);else expect(contract.data.legalPolicyReference).toContain('Original signed agreement');expect(app.attachments.some((row:any)=>row.recordId===contract.id&&row.filename===source.contract.document.fileName)).toBe(true);await studentTab(page,mapping.applicationId,'Agreement');await expect(page.getByRole('heading',{name:`${source.contract.reference} · Signed`,exact:true})).toBeVisible();await expect(page.locator('article.av8-record tbody tr')).toHaveCount(source.schedule.length);await page.screenshot({path:`${out}/opening-original-agreement.png`,fullPage:true});}expect(app.finance.unappliedMinor).toBe(fixture.expectedBalances.unallocatedReceiptMinor);for(const pending of source.pendingRefunds||[]){const refund=app.records.find((record:any)=>record.kind==='refund'&&record.data.sourceId===pending.sourceId);expect(refund.status).toBe('DECISION_REQUIRED');expect(refund.data.deadline).toBe(pending.deadline);expect(refund.data.noAutomaticPayout).toBe(true);}originals.push({mapping,app});}
 await page.goto('/av8/settings');await ready(page);const repeatPreview=await preview(manifest,'synthetic-reviewed-opening.json');expect(repeatPreview.valid).toBe(true);expect(repeatPreview.existingRows.length).toBeGreaterThan(0);const repeated=await commit('Synthetic source replay verification under a distinct request identity');expect(repeated.applications).toEqual(imported.applications);expect((await get('/av8/opening')).filter((batch:any)=>batch.source_system===manifest.sourceSystem)).toHaveLength(1);for(const original of originals){const after=await application(page,original.mapping.applicationId);expect(after.finance.schedule).toEqual(original.app.finance.schedule);expect(after.attachments).toEqual(original.app.attachments);expect(after.finance.funds).toEqual(original.app.finance.funds);}const afterBank=await get(`/banking?bankAccountId=${fixture.bankAccountId}`);expect(afterBank.transactionPagination.total).toBe(beforeBank.transactionPagination.total);expect(afterBank.transactions).toEqual(beforeBank.transactions);expect(await get(`/journals/${manifest.openingJournalId}`)).toEqual(beforeJournal);const resources=await get(`/banking/resources?search=${encodeURIComponent(fixture.bankName)}`);const bank=resources.rows.find((row:any)=>row.id===fixture.bankAccountId);expect(bank.originalBalanceMinor).toBe(fixture.expectedBalances.originalMinor);expect(bank.bookBalanceMinor).toBe(fixture.expectedBalances.bookMinor);await writeFile(`${out}/opening-import.json`,JSON.stringify({synthetic:true,sourceSystem:manifest.sourceSystem,applicationCount:imported.applications.length,totals:imported.totals,createdCashTransactions:0,createdJournals:0,originalSignedEvidencePreserved:true,sourceReplayPreservedMappings:true},null,2));
});
